import{_ as o,c as t,o as r,a5 as c}from"./chunks/framework.DuCYAsAJ.js";const h=JSON.parse('{"title":"Count 读链路与缓存失效","description":"","frontmatter":{"title":"Count 读链路与缓存失效","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#5.2","branch":"main","level":1,"order":5.2},"headers":[],"relativePath":"posts/projects/zfeed/05-count-rpc-service/02-count-read-chain-and-cache-invalidation.md","filePath":"posts/projects/zfeed/05-count-rpc-service/02-count-read-chain-and-cache-invalidation.md","lastUpdated":1779632679000}'),a={name:"posts/projects/zfeed/05-count-rpc-service/02-count-read-chain-and-cache-invalidation.md"};function i(l,e,n,p,g,u){return r(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="count-读链路与缓存失效" tabindex="-1">Count 读链路与缓存失效 <a class="header-anchor" href="#count-读链路与缓存失效" aria-label="Permalink to &quot;Count 读链路与缓存失效&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/getmelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/getmelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/getmelogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/getmelogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryfollowerslogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryfollowerslogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryuserprofilelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryuserprofilelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryuserprofilelogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryuserprofilelogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_bucket_cleanup/hot_bucket_cleanup_job.go" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_bucket_cleanup/hot_bucket_cleanup_job.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_cold_rebuild/hot_cold_rebuild_job.go" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_cold_rebuild/hot_cold_rebuild_job.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_snapshot_refresh/hot_snapshot_refresh_job.go" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_snapshot_refresh/hot_snapshot_refresh_job.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/common/consts/redis/redis_consts.go" target="_blank" rel="noreferrer">app/rpc/count/internal/common/consts/redis/redis_consts.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/batchgetcountlogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/batchgetcountlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_helper.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_helper.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getuserprofilecountslogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getuserprofilecountslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/inclogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/inclogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/read_path_test.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/read_path_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/svc/delayed_cache_invalidator.go" target="_blank" rel="noreferrer">app/rpc/count/internal/svc/delayed_cache_invalidator.go</a></li></ul></details><p><code>count-rpc</code> 服务为点赞、评论、收藏和关注等互动指标提供高性能读链路。它采用多层方案：通过 Redis 缓存和分布式锁防止缓存击穿，通过批量查询优化 Feed 补全，并使用专门的延迟失效策略在数据库写入后维持最终一致性。</p><h2 id="count-读取流程与缓存策略" tabindex="-1">Count 读取流程与缓存策略 <a class="header-anchor" href="#count-读取流程与缓存策略" aria-label="Permalink to &quot;Count 读取流程与缓存策略&quot;">​</a></h2><p>读链路用于处理来自 <code>front-api</code>（用户资料）和其他 RPC 服务（例如 <code>content-rpc</code> 的 Feed item 计数）的高频请求。</p><h3 id="关键组件" tabindex="-1">关键组件 <a class="header-anchor" href="#关键组件" aria-label="Permalink to &quot;关键组件&quot;">​</a></h3><ul><li><code>GetCountLogic</code>：使用 cache-aside 逻辑处理单个计数读取。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L19-L24" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#19-24</a></li><li><code>BatchGetCountLogic</code>：通过按 <code>BizType</code> 和 <code>TargetType</code> 对 key 分组，执行高效 MySQL <code>IN</code> 查询，从而优化多计数读取。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/batchgetcountlogic.go#L17-L22" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/batchgetcountlogic.go#17-22</a></li><li>Redis 缓存：存储序列化计数值，并使用带抖动的 TTL（24 小时 + 随机偏移），避免缓存同时过期。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/common/consts/redis/redis_consts.go#L7-L9" target="_blank" rel="noreferrer">app/rpc/count/internal/common/consts/redis/redis_consts.go#7-9</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_helper.go#L61-L63" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_helper.go#61-63</a></li><li>分布式锁：使用 <code>redislock</code> 确保缓存未命中时，只有一个请求重建特定 key 的缓存，防止“惊群”问题。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L75-L77" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#75-77</a></li></ul><h3 id="序列-单个计数读取" tabindex="-1">序列：单个计数读取 <a class="header-anchor" href="#序列-单个计数读取" aria-label="Permalink to &quot;序列：单个计数读取&quot;">​</a></h3><ol><li>查询缓存：尝试读取 key <code>count:value:{biz}:{target_type}:{target_id}</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L43-L47" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#43-47</a></li><li>加锁：缓存未命中时，获取 Redis 锁。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L75-L79" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#75-79</a></li><li>加载数据库：通过 <code>CountValueRepository</code> 从 <code>zfeed_count_value</code> 表读取值。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L133-L144" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#133-144</a></li><li>重建缓存：设置 Redis key，并释放锁。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L121-L130" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#121-130</a></li></ol><h3 id="图-读链路逻辑" tabindex="-1">图：读链路逻辑 <a class="header-anchor" href="#图-读链路逻辑" aria-label="Permalink to &quot;图：读链路逻辑&quot;">​</a></h3><p>该图将 <code>count-rpc</code> 逻辑实体连接到底层数据存储。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L35-L54" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#35-54</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_helper.go#L34-L51" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_helper.go#34-51</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/common/consts/redis/redis_consts.go#L5-L11" target="_blank" rel="noreferrer">app/rpc/count/internal/common/consts/redis/redis_consts.go#5-11</a></p><h2 id="用户资料计数聚合" tabindex="-1">用户资料计数聚合 <a class="header-anchor" href="#用户资料计数聚合" aria-label="Permalink to &quot;用户资料计数聚合&quot;">​</a></h2><p><code>GetUserProfileCounts</code> 方法会聚合用户资料页所需的多项指标。不同于单个计数器，该响应会作为 JSON 对象缓存，其中包含 <code>FollowingCount</code>、<code>FollowedCount</code>、<code>LikeCount</code> 和 <code>FavoriteCount</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_helper.go#L27-L32" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_helper.go#27-32</a></p><p>需要注意的是，ContentCount（用户已发布公开文章/视频数量）从不缓存进这个 JSON blob。它始终直接查询 MySQL 的 <code>zfeed_content</code> 表，以确保用户自己的资料页获得绝对准确的内容数量。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getuserprofilecountslogic.go#L174-L185" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getuserprofilecountslogic.go#174-185</a></p><h3 id="数据流-资料聚合" tabindex="-1">数据流：资料聚合 <a class="header-anchor" href="#数据流-资料聚合" aria-label="Permalink to &quot;数据流：资料聚合&quot;">​</a></h3><ol><li>逻辑入口：调用 <code>GetUserProfileCounts</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getuserprofilecountslogic.go#L39-L39" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getuserprofilecountslogic.go#39</a></li><li>缓存查找：key 为 <code>count:user:profile:{userId}</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_helper.go#L53-L55" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_helper.go#53-55</a></li><li>数据库求和：如果缓存未命中，服务会执行 <code>SumByOwner</code> 查询，聚合用户所有内容收到的点赞/收藏。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getuserprofilecountslogic.go#L143-L150" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getuserprofilecountslogic.go#143-150</a></li><li>实时内容数：调用 <code>queryContentCount</code> 查询 <code>zfeed_content</code>，条件为 <code>status=30</code> 且 <code>visibility=10</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getuserprofilecountslogic.go#L187-L206" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getuserprofilecountslogic.go#187-206</a></li></ol><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getuserprofilecountslogic.go#L44-L54" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getuserprofilecountslogic.go#44-54</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getuserprofilecountslogic.go#L138-L172" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getuserprofilecountslogic.go#138-172</a></p><h2 id="缓存失效策略" tabindex="-1">缓存失效策略 <a class="header-anchor" href="#缓存失效策略" aria-label="Permalink to &quot;缓存失效策略&quot;">​</a></h2><p>为了防止计数递增后出现旧读（例如用户点击“点赞”之后），系统使用延迟双删策略。</p><h3 id="delayed-cache-invalidator" tabindex="-1">Delayed Cache Invalidator <a class="header-anchor" href="#delayed-cache-invalidator" aria-label="Permalink to &quot;Delayed Cache Invalidator&quot;">​</a></h3><p>当 <code>CountOperator</code> 更新数据库后（由 Canal binlog 事件触发），它会通知 <code>DelayedCacheInvalidator</code>。该组件会清理 Redis 缓存，迫使后续读取从最新数据库状态重建。</p><table tabindex="0"><thead><tr><th>步骤</th><th>动作</th><th>实体</th><th>目的</th></tr></thead><tbody><tr><td>1</td><td>立即删除</td><td><code>Redis.Del</code></td><td>DB 写入后立即移除可能过期的数据。</td></tr><tr><td>2</td><td>延迟任务</td><td><code>time.AfterFunc</code></td><td>在短暂缓冲后调度第二次删除，例如 1-2 秒。</td></tr><tr><td>3</td><td>最终删除</td><td><code>Redis.Del</code></td><td>清理数据库复制延迟期间可能被并发重建出来的旧缓存。</td></tr></tbody></table><h3 id="图-写后失效" tabindex="-1">图：写后失效 <a class="header-anchor" href="#图-写后失效" aria-label="Permalink to &quot;图：写后失效&quot;">​</a></h3><p>该图展示 <code>CountOperator</code> 与 <code>DelayedCacheInvalidator</code> 之间的交互。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/inclogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/inclogic.go</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/svc/delayed_cache_invalidator.go" target="_blank" rel="noreferrer">app/rpc/count/internal/svc/delayed_cache_invalidator.go</a></p><h2 id="front-api-集成与降级" tabindex="-1">Front-API 集成与降级 <a class="header-anchor" href="#front-api-集成与降级" aria-label="Permalink to &quot;Front-API 集成与降级&quot;">​</a></h2><p><code>front-api</code> 会在 <code>GetMe</code> 和 <code>QueryUserProfile</code> 逻辑中聚合计数数据。为保持高可用，这些调用被包裹在 <code>sync.WaitGroup</code> 中，并设置严格超时（默认 200ms）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go#L12-L28" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go#12-28</a></p><h3 id="优雅降级" tabindex="-1">优雅降级 <a class="header-anchor" href="#优雅降级" aria-label="Permalink to &quot;优雅降级&quot;">​</a></h3><p>如果 <code>count-rpc</code> 服务变慢或不可用：</p><ol><li>超时：请求通过 <code>context.WithTimeout</code> 取消。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go#L22-L23" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go#22-23</a></li><li>回退：逻辑捕获错误并返回 <code>defaultUserProfileCounts()</code>（所有计数为零），而不是让整个资料请求失败。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryuserprofilelogic.go#L80-L86" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryuserprofilelogic.go#80-86</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/getmelogic.go#L75-L81" target="_blank" rel="noreferrer">app/front/internal/logic/user/getmelogic.go#75-81</a></li><li>关注数据源优先级：对于 <code>FolloweeCount</code> 和 <code>FollowerCount</code>，API 优先使用 <code>interaction-rpc</code>（通过 <code>GetFollowSummary</code>）的数据；只有主来源失败时，才回退到 <code>count-rpc</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/profilecounts_helper.go#L50-L74" target="_blank" rel="noreferrer">app/front/internal/logic/user/profilecounts_helper.go#50-74</a></li></ol><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/getmelogic.go#L57-L60" target="_blank" rel="noreferrer">app/front/internal/logic/user/getmelogic.go#57-60</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryuserprofilelogic.go#L61-L64" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryuserprofilelogic.go#61-64</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/queryuserprofilelogic_test.go#L111-L136" target="_blank" rel="noreferrer">app/front/internal/logic/user/queryuserprofilelogic_test.go#111-136</a></p>',32)])])}const b=o(a,[["render",i]]);export{h as __pageData,b as default};
